namespace CarScanner.Services.Localization;

// Batch 4: ranking/verification, service reset guides, paywall bullets, oil-life search, OEM function texts.
// Multi-line UI texts are translated line by line at runtime, so the rows below hold single lines
// (bullet and check-mark prefixes are stripped by the runtime before lookup). Order: tr, de, pl, es, pt, fr, it.
internal static partial class LanguagePacks
{
    private static IEnumerable<(string En, string[] T)> ExtraRows14() => new (string En, string[] T)[]
    {
        R("Loading ranking…", "Sıralama yükleniyor…", "Rangliste wird geladen …", "Wczytuję ranking…", "Cargando la clasificación…", "A carregar a classificação…", "Chargement du classement…", "Caricamento della classifica…"),
        R("Measure {0} in Performance Lab to get a place.", "Sıralamaya girmek için Performans Laboratuvarı’nda {0} ölç.", "Miss {0} im Performance-Labor, um einen Platz zu bekommen.", "Zmierz {0} w Laboratorium wydajności, aby zdobyć miejsce.", "Mide {0} en el Laboratorio de rendimiento para obtener un puesto.", "Meça {0} no Laboratório de desempenho para obter um lugar.", "Mesurez {0} dans le Laboratoire de performance pour obtenir une place.", "Misura {0} nel Laboratorio prestazioni per ottenere un posto."),
        R("Measurement", "Ölçüm", "Messung", "Pomiar", "Medición", "Medição", "Mesure", "Misurazione"),
        R("My model", "Benim modelim", "Mein Modell", "Mój model", "Mi modelo", "O meu modelo", "Mon modèle", "Il mio modello"),
        R("MY PLACE", "BENİM YERİM", "MEIN PLATZ", "MOJE MIEJSCE", "MI PUESTO", "O MEU LUGAR", "MA PLACE", "IL MIO POSTO"),
        R("No results for these filters.", "Bu filtreler için sonuç yok.", "Keine Ergebnisse für diese Filter.", "Brak wyników dla tych filtrów.", "No hay resultados para estos filtros.", "Sem resultados para estes filtros.", "Aucun résultat pour ces filtres.", "Nessun risultato per questi filtri."),
        R("Only runs measured from ECU Vehicle Speed (PID 01 0D) from a standstill are accepted: 0–100 km/h, 0–60 mph and ¼ mile (distance from ECU speed, so it is an estimate). The model and year must be VIN-confirmed. Implausible or insufficient measurements are rejected, and top results may be checked by our team.", "Yalnızca durağan halden ECU araç hızı (PID 01 0D) ile ölçülen denemeler kabul edilir: 0–100 km/sa, 0–60 mph ve ¼ mil (mesafe ECU hızından hesaplanır, bu yüzden tahmindir). Model ve yıl VIN ile doğrulanmış olmalıdır. Makul olmayan veya yetersiz ölçümler reddedilir ve en iyi sonuçlar ekibimiz tarafından kontrol edilebilir.", "Akzeptiert werden nur Läufe, die aus dem Stand mit der ECU-Fahrzeuggeschwindigkeit (PID 01 0D) gemessen wurden: 0–100 km/h, 0–60 mph und ¼ Meile (Strecke aus der ECU-Geschwindigkeit, daher eine Schätzung). Modell und Jahr müssen per VIN bestätigt sein. Unplausible oder unzureichende Messungen werden abgelehnt, und Spitzenergebnisse können von unserem Team geprüft werden.", "Akceptowane są tylko przejazdy zmierzone na podstawie prędkości pojazdu z ECU (PID 01 0D) z miejsca: 0–100 km/h, 0–60 mph i ¼ mili (dystans z prędkości ECU, więc to oszacowanie). Model i rocznik muszą być potwierdzone numerem VIN. Nieprawdopodobne lub niewystarczające pomiary są odrzucane, a najlepsze wyniki może sprawdzić nasz zespół.", "Solo se aceptan pruebas medidas con la velocidad del vehículo de la ECU (PID 01 0D) desde parado: 0–100 km/h, 0–60 mph y ¼ de milla (distancia calculada con la velocidad de la ECU, por lo que es una estimación). El modelo y el año deben estar confirmados por VIN. Las mediciones inverosímiles o insuficientes se rechazan y nuestro equipo puede revisar los mejores resultados.", "Só são aceites medições feitas com a velocidade do veículo da ECU (PID 01 0D) a partir de parado: 0–100 km/h, 0–60 mph e ¼ de milha (distância calculada pela velocidade da ECU, por isso é uma estimativa). O modelo e o ano têm de estar confirmados pelo VIN. Medições implausíveis ou insuficientes são rejeitadas e os melhores resultados podem ser verificados pela nossa equipa.", "Seuls les essais mesurés à partir de la vitesse du véhicule de l’ECU (PID 01 0D) depuis l’arrêt sont acceptés : 0–100 km/h, 0–60 mph et ¼ de mile (distance calculée d’après la vitesse de l’ECU, donc une estimation). Le modèle et l’année doivent être confirmés par le VIN. Les mesures invraisemblables ou insuffisantes sont rejetées et les meilleurs résultats peuvent être vérifiés par notre équipe.", "Sono accettate solo le prove misurate con la velocità del veicolo dalla ECU (PID 01 0D) da fermo: 0–100 km/h, 0–60 mph e ¼ di miglio (distanza ricavata dalla velocità ECU, quindi è una stima). Modello e anno devono essere confermati dal VIN. Le misurazioni non plausibili o insufficienti vengono rifiutate e i risultati migliori possono essere controllati dal nostro team."),
        R("Period", "Dönem", "Zeitraum", "Okres", "Periodo", "Período", "Période", "Periodo"),
        R("Ranking", "Sıralama", "Rangliste", "Ranking", "Clasificación", "Classificação", "Classement", "Classifica"),
        R("Results checked by video or by our team", "Sonuçlar video veya ekibimiz tarafından kontrol edilir", "Ergebnisse per Video oder durch unser Team geprüft", "Wyniki sprawdzone na wideo lub przez nasz zespół", "Resultados comprobados por vídeo o por nuestro equipo", "Resultados verificados por vídeo ou pela nossa equipa", "Résultats vérifiés par vidéo ou par notre équipe", "Risultati verificati tramite video o dal nostro team"),
        R("SEND VIDEO FOR REVIEW", "VİDEOYU İNCELEME İÇİN GÖNDER", "VIDEO ZUR PRÜFUNG SENDEN", "WYŚLIJ WIDEO DO SPRAWDZENIA", "ENVIAR VÍDEO PARA REVISIÓN", "ENVIAR VÍDEO PARA ANÁLISE", "ENVOYER LA VIDÉO POUR VÉRIFICATION", "INVIA IL VIDEO PER LA REVISIONE"),
        R("Sending the video…", "Video gönderiliyor…", "Video wird gesendet …", "Wysyłam wideo…", "Enviando el vídeo…", "A enviar o vídeo…", "Envoi de la vidéo…", "Invio del video…"),
        R("this month", "bu ay", "diesen Monat", "w tym miesiącu", "este mes", "este mês", "ce mois-ci", "questo mese"),
        R("This month", "Bu ay", "Diesen Monat", "W tym miesiącu", "Este mes", "Este mês", "Ce mois-ci", "Questo mese"),
