        R("This year", "Bu yıl", "Dieses Jahr", "W tym roku", "Este año", "Este ano", "Cette année", "Quest’anno"),
        R("UNDER REVIEW", "İNCELENİYOR", "IN PRÜFUNG", "W TRAKCIE SPRAWDZANIA", "EN REVISIÓN", "EM ANÁLISE", "EN COURS DE VÉRIFICATION", "IN REVISIONE"),
        R("verified", "doğrulandı", "verifiziert", "zweryfikowano", "verificado", "verificado", "vérifié", "verificato"),
        R("Verified only", "Yalnızca doğrulananlar", "Nur verifizierte", "Tylko zweryfikowane", "Solo verificados", "Só verificados", "Vérifiés uniquement", "Solo verificati"),
        R("Your result is under review. Top places need a video: open Performance Video, measure the run again while recording, and the video is sent automatically.", "Sonucun inceleniyor. İlk sıralar video gerektirir: Performans Videosu’nu aç, kayıt yaparken denemeyi yeniden ölç; video otomatik gönderilir.", "Dein Ergebnis wird geprüft. Für Spitzenplätze ist ein Video nötig: Öffne Performance-Video, miss den Lauf mit Aufnahme erneut, dann wird das Video automatisch gesendet.", "Twój wynik jest sprawdzany. Czołowe miejsca wymagają wideo: otwórz Wideo wydajności, zmierz przejazd ponownie podczas nagrywania, a wideo zostanie wysłane automatycznie.", "Tu resultado está en revisión. Los primeros puestos requieren un vídeo: abre Vídeo de rendimiento, vuelve a medir la prueba mientras grabas y el vídeo se envía automáticamente.", "O seu resultado está em análise. Os primeiros lugares exigem um vídeo: abra o Vídeo de desempenho, meça a prova novamente enquanto grava e o vídeo é enviado automaticamente.", "Votre résultat est en cours de vérification. Les premières places exigent une vidéo : ouvrez Vidéo de performance, refaites la mesure en filmant, et la vidéo est envoyée automatiquement.", "Il tuo risultato è in revisione. I primi posti richiedono un video: apri Video prestazioni, misura di nuovo la prova mentre registri e il video viene inviato automaticamente."),
        R("At the moment of the fault: {0}", "Arıza anında: {0}", "Zum Zeitpunkt des Fehlers: {0}", "W chwili wystąpienia usterki: {0}", "En el momento de la avería: {0}", "No momento da avaria: {0}", "Au moment du défaut : {0}", "Al momento del guasto: {0}"),
        R("Module bytes: {0} · status 0x{1}", "Modül baytları: {0} · durum 0x{1}", "Modulbytes: {0} · Status 0x{1}", "Bajty modułu: {0} · status 0x{1}", "Bytes del módulo: {0} · estado 0x{1}", "Bytes do módulo: {0} · estado 0x{1}", "Octets du module : {0} · statut 0x{1}", "Byte del modulo: {0} · stato 0x{1}"),
        R(" · ECU backup saved", " · ECU yedeği kaydedildi", " · ECU-Sicherung gespeichert", " · kopia ECU zapisana", " · copia de la ECU guardada", " · cópia da ECU guardada", " · sauvegarde ECU enregistrée", " · backup ECU salvato"),
        R(" · until {0}", " · {0} tarihine kadar", " · bis {0}", " · do {0}", " · hasta {0}", " · até {0}", " · jusqu’au {0}", " · fino al {0}"),
        R("Before execution the app will re-check voltage, speed, engine state and the exact ECU definition. Continue?", "Çalıştırmadan önce uygulama voltajı, hızı, motor durumunu ve tam ECU tanımını yeniden kontrol edecek. Devam edilsin mi?", "Vor der Ausführung prüft die App Spannung, Geschwindigkeit, Motorzustand und die genaue ECU-Definition erneut. Fortfahren?", "Przed wykonaniem aplikacja ponownie sprawdzi napięcie, prędkość, stan silnika i dokładną definicję ECU. Kontynuować?", "Antes de ejecutar, la app volverá a comprobar la tensión, la velocidad, el estado del motor y la definición exacta de la ECU. ¿Continuar?", "Antes de executar, a app volta a verificar a tensão, a velocidade, o estado do motor e a definição exata da ECU. Continuar?", "Avant l’exécution, l’app revérifiera la tension, la vitesse, l’état du moteur et la définition exacte de l’ECU. Continuer ?", "Prima dell’esecuzione l’app ricontrollerà tensione, velocità, stato del motore e la definizione esatta della ECU. Continuare?"),
        R("{0} — instructions displayed.", "{0} — talimatlar gösterildi.", "{0} — Anleitung angezeigt.", "{0} — wyświetlono instrukcję.", "{0}: instrucciones mostradas.", "{0} — instruções apresentadas.", "{0} — instructions affichées.", "{0} — istruzioni mostrate."),
        R("{0} ({1}) will be reset.", "{0} ({1}) sıfırlanacak.", "{0} ({1}) wird zurückgesetzt.", "{0} ({1}) zostanie zresetowane.", "Se restablecerá {0} ({1}).", "{0} ({1}) será reposto.", "{0} ({1}) sera réinitialisé.", "{0} ({1}) verrà azzerato."),
        R("Do this only after the service was done.", "Bunu yalnızca servis yapıldıktan sonra yap.", "Tue das nur, nachdem der Service durchgeführt wurde.", "Zrób to dopiero po wykonaniu serwisu.", "Hazlo solo después de haber hecho el servicio.", "Faça isto apenas depois de o serviço ter sido feito.", "Ne le faites qu’après l’entretien.", "Fallo solo dopo aver eseguito l’intervento."),
        R("Car in P, ignition on.", "Araç P’de, kontak açık.", "Fahrzeug in P, Zündung an.", "Pojazd w P, zapłon włączony.", "Coche en P, contacto dado.", "Carro em P, ignição ligada.", "Voiture en P, contact mis.", "Auto in P, quadro acceso."),
        R("Continue?", "Devam edilsin mi?", "Fortfahren?", "Kontynuować?", "¿Continuar?", "Continuar?", "Continuer ?", "Continuare?"),
        R("{0} fault(s)", "{0} arıza", "{0} Fehler", "{0} usterek", "{0} avería(s)", "{0} avaria(s)", "{0} défaut(s)", "{0} guasto/i"),
        R("{0} is not active on your account ({1}) yet.", "{0} hesabında ({1}) henüz etkin değil.", "{0} ist auf deinem Konto ({1}) noch nicht aktiv.", "{0} nie jest jeszcze aktywne na Twoim koncie ({1}).", "{0} aún no está activo en tu cuenta ({1}).", "{0} ainda não está ativo na sua conta ({1}).", "{0} n’est pas encore actif sur votre compte ({1}).", "{0} non è ancora attivo sul tuo account ({1})."),
        R("{0} is temporarily unavailable. Check your connection and try again.", "{0} geçici olarak kullanılamıyor. Bağlantını kontrol et ve tekrar dene.", "{0} ist vorübergehend nicht verfügbar. Prüfe deine Verbindung und versuche es erneut.", "{0} jest tymczasowo niedostępne. Sprawdź połączenie i spróbuj ponownie.", "{0} no está disponible temporalmente. Revisa tu conexión e inténtalo de nuevo.", "{0} está temporariamente indisponível. Verifique a sua ligação e tente novamente.", "{0} est temporairement indisponible. Vérifiez votre connexion et réessayez.", "{0} non è temporaneamente disponibile. Controlla la connessione e riprova."),
        R("{0} km driven", "{0} km sürüldü", "{0} km gefahren", "przejechano {0} km", "{0} km recorridos", "{0} km percorridos", "{0} km parcourus", "{0} km percorsi"),
        R("{0} modules · from the scan at {1}", "{0} modül · {1} tarihindeki taramadan", "{0} Module · aus dem Scan von {1}", "{0} modułów · ze skanowania z {1}", "{0} módulos · del análisis de {1}", "{0} módulos · da análise de {1}", "{0} modules · de l’analyse du {1}", "{0} moduli · dalla scansione del {1}"),
        R("{0} value(s) answered, but none equals {1}%. Check the dashboard %.", "{0} değer yanıt verdi ama hiçbiri %{1}’e eşit değil. Gösterge panelindeki %’yi kontrol et.", "{0} Wert(e) haben geantwortet, aber keiner entspricht {1} %. Prüfe den Prozentwert am Kombiinstrument.", "Odpowiedziało {0} wartości, ale żadna nie równa się {1}%. Sprawdź % na zestawie wskaźników.", "{0} valor(es) respondieron, pero ninguno es igual a {1} %. Revisa el % del cuadro.", "{0} valor(es) responderam, mas nenhum é igual a {1}%. Verifique a % no painel.", "{0} valeur(s) ont répondu, mais aucune n’est égale à {1} %. Vérifiez le % au tableau de bord.", "{0} valore/i hanno risposto, ma nessuno è uguale a {1}%. Controlla la % sul cruscotto."),
        R("{0} value(s) answered. Enter the dashboard oil % and repeat to pick the right one.", "{0} değer yanıt verdi. Gösterge panelindeki yağ %’sini gir ve doğru olanı seçmek için tekrarla.", "{0} Wert(e) haben geantwortet. Gib den Öl-Prozentwert vom Kombiinstrument ein und wiederhole, um den richtigen zu wählen.", "Odpowiedziało {0} wartości. Wpisz % oleju z zestawu wskaźników i powtórz, aby wybrać właściwą.", "{0} valor(es) respondieron. Introduce el % de aceite del cuadro y repite para elegir el correcto.", "{0} valor(es) responderam. Introduza a % de óleo do painel e repita para escolher o correto.", "{0} valeur(s) ont répondu. Saisissez le % d’huile du tableau de bord et recommencez pour choisir la bonne.", "{0} valore/i hanno risposto. Inserisci la % olio del cruscotto e ripeti per scegliere quello giusto."),
        R("Display cluster: ignition ON (engine off) → steering buttons Settings (gear) → Vehicle Settings → Scheduled Maintenance → Yes.", "Gösterge paneli: kontak AÇIK (motor kapalı) → direksiyon düğmeleri Ayarlar (dişli) → Araç Ayarları → Planlı Bakım → Evet.", "Kombiinstrument: Zündung AN (Motor aus) → Lenkradtasten Einstellungen (Zahnrad) → Fahrzeugeinstellungen → Planmäßige Wartung → Ja.", "Zestaw wskaźników: zapłon WŁ. (silnik wyłączony) → przyciski na kierownicy Ustawienia (zębatka) → Ustawienia pojazdu → Zaplanowany przegląd → Tak.", "Cuadro: contacto dado (motor apagado) → botones del volante Ajustes (engranaje) → Ajustes del vehículo → Mantenimiento programado → Sí.", "Painel: ignição ligada (motor desligado) → botões do volante Definições (roda dentada) → Definições do veículo → Manutenção programada → Sim.", "Combiné d’instruments : contact mis (moteur arrêté) → boutons du volant Réglages (engrenage) → Réglages du véhicule → Entretien programmé → Oui.", "Quadro strumenti: quadro acceso (motore spento) → pulsanti del volante Impostazioni (ingranaggio) → Impostazioni veicolo → Manutenzione programmata → Sì."),
        R("Older cluster: ignition OFF, show Trip A, hold the Trip button, turn ignition ON (no engine) and keep holding until 000000 appears.", "Eski gösterge paneli: kontak KAPALI, Trip A’yı göster, Trip düğmesini basılı tut, kontağı AÇ (motoru çalıştırma) ve 000000 görünene kadar basılı tut.", "Älteres Kombiinstrument: Zündung AUS, Trip A anzeigen, Trip-Taste gedrückt halten, Zündung AN (ohne Motor) und halten, bis 000000 erscheint.", "Starszy zestaw wskaźników: zapłon WYŁ., wyświetl Trip A, przytrzymaj przycisk Trip, włącz zapłon (bez uruchamiania silnika) i trzymaj, aż pojawi się 000000.", "Cuadro antiguo: contacto apagado, muestra Trip A, mantén pulsado el botón Trip, da el contacto (sin arrancar) y sigue manteniéndolo hasta que aparezca 000000.", "Painel mais antigo: ignição desligada, mostre o Trip A, mantenha premido o botão Trip, ligue a ignição (sem ligar o motor) e continue a premir até aparecer 000000.", "Ancien combiné : contact coupé, affichez Trip A, maintenez le bouton Trip, mettez le contact (sans démarrer) et continuez à maintenir jusqu’à l’affichage de 000000.", "Quadro più vecchio: quadro spento, mostra Trip A, tieni premuto il pulsante Trip, accendi il quadro (senza avviare il motore) e continua a tenere premuto finché compare 000000."),
        R("Ignition ON → cluster or infotainment Settings → Maintenance/Service → Reset. Exact steps are in the owner's manual.", "Kontak AÇIK → gösterge paneli veya multimedya Ayarlar → Bakım/Servis → Sıfırla. Kesin adımlar kullanım kılavuzunda.", "Zündung AN → Einstellungen im Kombiinstrument oder Infotainment → Wartung/Service → Zurücksetzen. Die genauen Schritte stehen in der Betriebsanleitung.", "Zapłon WŁ. → Ustawienia w zestawie wskaźników lub systemie multimedialnym → Konserwacja/Serwis → Resetuj. Dokładne kroki są w instrukcji obsługi.", "Contacto dado → Ajustes del cuadro o del infoentretenimiento → Mantenimiento/Servicio → Restablecer. Los pasos exactos están en el manual del propietario.", "Ignição ligada → Definições do painel ou do infoentretenimento → Manutenção/Serviço → Repor. Os passos exatos estão no manual do proprietário.", "Contact mis → Réglages du combiné ou de l’infodivertissement → Entretien/Service → Réinitialiser. Les étapes exactes figurent dans le manuel du propriétaire.", "Quadro acceso → Impostazioni del cruscotto o dell’infotainment → Manutenzione/Assistenza → Azzera. I passaggi esatti sono nel manuale d’uso."),
        R("Ignition ON → cluster Settings → Maintenance → Oil → Reset.", "Kontak AÇIK → gösterge paneli Ayarlar → Bakım → Yağ → Sıfırla.", "Zündung AN → Einstellungen im Kombiinstrument → Wartung → Öl → Zurücksetzen.", "Zapłon WŁ. → Ustawienia zestawu wskaźników → Konserwacja → Olej → Resetuj.", "Contacto dado → Ajustes del cuadro → Mantenimiento → Aceite → Restablecer.", "Ignição ligada → Definições do painel → Manutenção → Óleo → Repor.", "Contact mis → Réglages du combiné → Entretien → Huile → Réinitialiser.", "Quadro acceso → Impostazioni del cruscotto → Manutenzione → Olio → Azzera."),
        R("Ignition ON → cluster Settings → Service → Reset (or MMI: Car → Service → Reset).", "Kontak AÇIK → gösterge paneli Ayarlar → Servis → Sıfırla (veya MMI: Araç → Servis → Sıfırla).", "Zündung AN → Einstellungen im Kombiinstrument → Service → Zurücksetzen (oder MMI: Fahrzeug → Service → Zurücksetzen).", "Zapłon WŁ. → Ustawienia zestawu wskaźników → Serwis → Resetuj (lub MMI: Pojazd → Serwis → Resetuj).", "Contacto dado → Ajustes del cuadro → Servicio → Restablecer (o MMI: Coche → Servicio → Restablecer).", "Ignição ligada → Definições do painel → Serviço → Repor (ou MMI: Carro → Serviço → Repor).", "Contact mis → Réglages du combiné → Service → Réinitialiser (ou MMI : Voiture → Service → Réinitialiser).", "Quadro acceso → Impostazioni del cruscotto → Assistenza → Azzera (oppure MMI: Auto → Assistenza → Azzera)."),
        R("Ignition ON → cluster Settings → Vehicle → Oil Life → hold OK.", "Kontak AÇIK → gösterge paneli Ayarlar → Araç → Yağ Ömrü → OK’i basılı tut.", "Zündung AN → Einstellungen im Kombiinstrument → Fahrzeug → Öllebensdauer → OK gedrückt halten.", "Zapłon WŁ. → Ustawienia zestawu wskaźników → Pojazd → Żywotność oleju → przytrzymaj OK.", "Contacto dado → Ajustes del cuadro → Vehículo → Vida del aceite → mantén pulsado OK.", "Ignição ligada → Definições do painel → Veículo → Vida do óleo → mantenha premido OK.", "Contact mis → Réglages du combiné → Véhicule → Durée de vie de l’huile → maintenez OK.", "Quadro acceso → Impostazioni del cruscotto → Veicolo → Vita dell’olio → tieni premuto OK."),
        R("Older models: ignition ON, press accelerator and brake fully together for ~20 s.", "Eski modeller: kontak AÇIK, gaz ve fren pedalına birlikte tam basıp ~20 sn tut.", "Ältere Modelle: Zündung AN, Gas- und Bremspedal gleichzeitig ca. 20 s voll durchtreten.", "Starsze modele: zapłon WŁ., wciśnij do oporu jednocześnie gaz i hamulec na ok. 20 s.", "Modelos antiguos: contacto dado, pisa a fondo el acelerador y el freno a la vez durante ~20 s.", "Modelos mais antigos: ignição ligada, pressione o acelerador e o travão a fundo em simultâneo durante ~20 s.", "Anciens modèles : contact mis, appuyez à fond sur l’accélérateur et le frein ensemble pendant ~20 s.", "Modelli più vecchi: quadro acceso, premi a fondo acceleratore e freno insieme per ~20 s."),
        R("Ignition ON → cluster User Settings → Service Interval → Reset (or infotainment: Vehicle → Service).", "Kontak AÇIK → gösterge paneli Kullanıcı Ayarları → Servis Aralığı → Sıfırla (veya multimedya: Araç → Servis).", "Zündung AN → Kombiinstrument Benutzereinstellungen → Serviceintervall → Zurücksetzen (oder Infotainment: Fahrzeug → Service).", "Zapłon WŁ. → Ustawienia użytkownika zestawu wskaźników → Interwał serwisowy → Resetuj (lub system multimedialny: Pojazd → Serwis).", "Contacto dado → Ajustes de usuario del cuadro → Intervalo de servicio → Restablecer (o infoentretenimiento: Vehículo → Servicio).", "Ignição ligada → Definições de utilizador do painel → Intervalo de serviço → Repor (ou infoentretenimento: Veículo → Serviço).", "Contact mis → Réglages utilisateur du combiné → Intervalle d’entretien → Réinitialiser (ou infodivertissement : Véhicule → Service).", "Quadro acceso → Impostazioni utente del cruscotto → Intervallo di assistenza → Azzera (oppure infotainment: Veicolo → Assistenza)."),
        R("Ignition ON → hold the odometer/Trip button until the service menu shows → choose Oil → Reset.", "Kontak AÇIK → servis menüsü görünene kadar kilometre sayacı/Trip düğmesini basılı tut → Yağ → Sıfırla seç.", "Zündung AN → Kilometerzähler-/Trip-Taste halten, bis das Servicemenü erscheint → Öl → Zurücksetzen wählen.", "Zapłon WŁ. → przytrzymaj przycisk licznika/Trip, aż pojawi się menu serwisowe → wybierz Olej → Resetuj.", "Contacto dado → mantén pulsado el botón del cuentakilómetros/Trip hasta que aparezca el menú de servicio → elige Aceite → Restablecer.", "Ignição ligada → mantenha premido o botão do conta-quilómetros/Trip até aparecer o menu de serviço → escolha Óleo → Repor.", "Contact mis → maintenez le bouton du compteur/Trip jusqu’à l’affichage du menu service → choisissez Huile → Réinitialiser.", "Quadro acceso → tieni premuto il pulsante contachilometri/Trip finché compare il menu di assistenza → scegli Olio → Azzera."),
        R("Ignition ON → Settings → Maintenance → Scheduled → Reset.", "Kontak AÇIK → Ayarlar → Bakım → Planlı → Sıfırla.", "Zündung AN → Einstellungen → Wartung → Planmäßig → Zurücksetzen.", "Zapłon WŁ. → Ustawienia → Konserwacja → Zaplanowane → Resetuj.", "Contacto dado → Ajustes → Mantenimiento → Programado → Restablecer.", "Ignição ligada → Definições → Manutenção → Programada → Repor.", "Contact mis → Réglages → Entretien → Programmé → Réinitialiser.", "Quadro acceso → Impostazioni → Manutenzione → Programmata → Azzera."),
        R("Ignition ON → show oil % with SEL/RESET, hold 10 s until it blinks, then hold 5 s more.", "Kontak AÇIK → SEL/RESET ile yağ %’sini göster, yanıp sönene kadar 10 sn basılı tut, sonra 5 sn daha tut.", "Zündung AN → Öl-Prozentwert mit SEL/RESET anzeigen, 10 s halten, bis er blinkt, dann weitere 5 s halten.", "Zapłon WŁ. → wyświetl % oleju przyciskiem SEL/RESET, przytrzymaj 10 s do mrugania, potem jeszcze 5 s.", "Contacto dado → muestra el % de aceite con SEL/RESET, mantén 10 s hasta que parpadee y luego 5 s más.", "Ignição ligada → mostre a % de óleo com SEL/RESET, mantenha 10 s até piscar e depois mais 5 s.", "Contact mis → affichez le % d’huile avec SEL/RESET, maintenez 10 s jusqu’au clignotement, puis encore 5 s.", "Quadro acceso → mostra la % olio con SEL/RESET, tieni premuto 10 s finché lampeggia, poi altri 5 s."),
        R("Newer models: Settings → Vehicle → Maintenance Info → Reset.", "Yeni modeller: Ayarlar → Araç → Bakım Bilgisi → Sıfırla.", "Neuere Modelle: Einstellungen → Fahrzeug → Wartungsinfo → Zurücksetzen.", "Nowsze modele: Ustawienia → Pojazd → Informacje o konserwacji → Resetuj.", "Modelos nuevos: Ajustes → Vehículo → Información de mantenimiento → Restablecer.", "Modelos mais recentes: Definições → Veículo → Informações de manutenção → Repor.", "Modèles récents : Réglages → Véhicule → Infos d’entretien → Réinitialiser.", "Modelli più recenti: Impostazioni → Veicolo → Info manutenzione → Azzera."),
        R("Ignition ON → steering menu Service → ASSYST PLUS → Confirm service.", "Kontak AÇIK → direksiyon menüsü Servis → ASSYST PLUS → Servisi onayla.", "Zündung AN → Lenkradmenü Service → ASSYST PLUS → Service bestätigen.", "Zapłon WŁ. → menu na kierownicy Serwis → ASSYST PLUS → Potwierdź serwis.", "Contacto dado → menú del volante Servicio → ASSYST PLUS → Confirmar servicio.", "Ignição ligada → menu do volante Serviço → ASSYST PLUS → Confirmar serviço.", "Contact mis → menu du volant Service → ASSYST PLUS → Confirmer l’entretien.", "Quadro acceso → menu del volante Assistenza → ASSYST PLUS → Conferma intervento."),
        R("Ignition ON, engine off: slowly press the accelerator fully 3 times within 5 s.", "Kontak AÇIK, motor kapalı: 5 sn içinde gaz pedalına yavaşça 3 kez tam bas.", "Zündung AN, Motor aus: Gaspedal innerhalb von 5 s dreimal langsam ganz durchtreten.", "Zapłon WŁ., silnik wyłączony: w ciągu 5 s powoli wciśnij do oporu pedał gazu 3 razy.", "Contacto dado, motor apagado: pisa lentamente a fondo el acelerador 3 veces en 5 s.", "Ignição ligada, motor desligado: pressione lentamente o acelerador a fundo 3 vezes em 5 s.", "Contact mis, moteur arrêté : appuyez lentement à fond sur l’accélérateur 3 fois en 5 s.", "Quadro acceso, motore spento: premi lentamente a fondo l’acceleratore 3 volte entro 5 s."),
        R("Or cluster menu: Oil Life → hold Select/Reset.", "Veya gösterge paneli menüsü: Yağ Ömrü → Seç/Sıfırla’yı basılı tut.", "Oder Kombiinstrument-Menü: Öllebensdauer → Select/Reset gedrückt halten.", "Albo menu zestawu wskaźników: Żywotność oleju → przytrzymaj Select/Reset.", "O menú del cuadro: Vida del aceite → mantén pulsado Select/Reset.", "Ou menu do painel: Vida do óleo → mantenha premido Select/Reset.", "Ou menu du combiné : Durée de vie de l’huile → maintenez Select/Reset.", "Oppure menu del cruscotto: Vita dell’olio → tieni premuto Select/Reset."),
        R("+{0} VIN added.", "+{0} VIN eklendi.", "+{0} VIN hinzugefügt.", "Dodano +{0} VIN.", "Se añadieron +{0} VIN.", "Adicionados +{0} VIN.", "+{0} VIN ajouté(s).", "Aggiunti +{0} VIN."),
